""use client";

import { useState, useEffect } from "react";
import { useAppState } from "@/lib/state";

export function DevConsole() {
  const [isOpen, setIsOpen] = useState(false);
  const {
    state,
    setPersona,
    resetApp,
    fastForwardTimer,
    liftCooldown,
    addNotification,
  } = useAppState();

  const [timeLeft, setTimeLeft] = useState<string>("N/A");

  useEffect(() => {
    if (!state?.timerStart) {
      setTimeLeft("N/A");
      return;
    }
    const updateTimer = () => {
      const elapsed = Math.floor((Date.now() - state.timerStart!) / 1000);
      const remaining = (state?.timerDuration || 900) - elapsed;
      if (remaining <= 0) {
        setTimeLeft("0:00 (Expired)");
      } else {
        const mins = Math.floor(remaining / 60);
        const secs = remaining % 60;
        setTimeLeft(`${mins}:${secs < 10 ? "0" : ""}${secs}`);
      }
    };
    updateTimer();
    const interval = setInterval(updateTimer, 1000);
    return () => clearInterval(interval);
  }, [state?.timerStart, state?.timerDuration]);

  const userPersona = state?.userPersona || "james";

  return (
    <div className="fixed bottom-4 left-4 right-4 md:left-auto md:right-4 md:w-96 z-50 transition-all duration-300">
      {/* Trigger Bar */}
      <div
        onClick={() => setIsOpen(!isOpen)}
        className="bg-black/90 text-white px-4 py-3 rounded-2xl cursor-pointer flex justify-between items-center shadow-lg border border-white/10 backdrop-blur-md"
