"  // Auto-populate from state if they already exist, otherwise use default
  const [options, setOptions] = useState<MeetupOption[]>(() => {
    if (state?.proposals && state.proposals.length === 3) {
      return state.proposals;
    }
    return DEFAULT_PROPOSALS;
  });

  // Redirect if state phase changes
  useEffect(() => {
    if (state?.phase !== "proposing") {
      router.push("/");
    }
  }, [state?.phase]);

  // 15-minute timer countdown
  useEffect(() => {
    if (!state?.timerStart) return;
    const interval = setInterval(() => {
      const elapsed = Math.floor((Date.now() - state.timerStart!) / 1000);
      const remaining = (state?.timerDuration || 900) - elapsed;
      if (remaining <= 0) {
        setTimeLeft("0:00");
      } else {
        const mins = Math.floor(remaining / 60);
        const secs = remaining % 60;
        setTimeLeft(`${mins}:${secs < 10 ? "0" : ""}${secs}`);
      }
    }, 1000);
    return () => clearInterval(interval);
  }, [state?.timerStart, state?.timerDuration]);

  const handleLocationChange = (index: number, location: string) => {
    const updated = [...options];
    updated[index] = { ...updated[index], location };
    setOptions(updated);
  };

  const handleTimeChange = (index: number, time: string) => {
    const updated = [...options];
    updated[index] = { ...updated[index], time };
    setOptions(updated);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    submitProposals(options);
    router.push("/");
  };

  return (
    <div className="fixed inset-0 bg-background flex flex-col">
